const STORY_MEMORY_ORDER = new Map(['canon_fact', 'world_rule', 'character_state', 'voice_habit', 'event', 'chapter_summary'].map((type, index) => [type, index]))

export { STORY_MEMORY_ORDER }

function contextExcerpt(value, maxLength = 1600) {
  const text = typeof value === 'string' ? value.trim() : ''
  if (text.length <= maxLength) return text
  return `${text.slice(0, Math.floor(maxLength * 0.35))}\n…\n${text.slice(-Math.floor(maxLength * 0.65))}`
}

function workspaceSegment(value, fallback) {
  const normalized = String(value || fallback || '')
    .replace(/[\\/:*?"<>|\u0000-\u001f]/g, '-')
    .replace(/[.\s]+$/g, '')
    .trim()
    .slice(0, 100)
  return normalized || fallback
}

function taggedStoryFilePath(idea) {
  const tag = Array.isArray(idea?.tags)
    ? idea.tags.find((item) => String(item).startsWith('文件:'))
    : null
  return tag ? String(tag).slice(3).trim() : ''
}

export function storyFilePath(idea) {
  const taggedPath = taggedStoryFilePath(idea)
  if (taggedPath) return taggedPath
  if (!idea?.title) return ''
  const folder = workspaceSegment(idea.folder || idea.label, '资料')
  const title = workspaceSegment(idea.title, idea.id || '未命名')
  return `${folder}/${title}.md`
}

export function chapterStoryFilePath(chapter) {
  const id = String(chapter?.id ?? '').padStart(3, '0')
  const title = workspaceSegment(chapter?.title, `第${id}章`)
  return `正文/${id}-${title}.md`
}

export function readStoryFileForAgent(db, userId, projectId, requestedPath) {
  const rawPath = String(requestedPath || '').replaceAll('\\', '/').trim().slice(0, 240)
  if (!rawPath || rawPath.startsWith('/') || /^[A-Za-z]:\//.test(rawPath)) return null
  const parts = rawPath.split('/').filter(Boolean)
  if (!parts.length || parts.some((part) => part === '.' || part === '..' || part.includes('\0'))) return null
  const path = parts.join('/')
  const project = db.projects.find((item) => item.id === projectId && item.userId === userId)
  if (!project) return null
  const idea = (db.ideas || []).find((item) => item.userId === userId
    && item.projectId === projectId
    && storyFilePath(item) === path)
  if (idea) {
    return {
      path,
      title: String(idea.title || path.split('/').at(-1) || '作品文件').slice(0, 160),
      category: String(idea.folder || idea.label || path.split('/')[0] || '资料').slice(0, 40),
      content: String(idea.body || '').replace(/\r\n?/g, '\n').slice(0, 50_000),
      updatedAt: idea.updatedAt || idea.createdAt || '',
    }
  }
  const chapter = (db.chapters?.[projectId] || []).find((item) => chapterStoryFilePath(item) === path)
  if (!chapter) return null
  return {
    path,
    title: String(chapter.title || path.split('/').at(-1) || '章节正文').slice(0, 160),
    category: '正文',
    content: String(db.drafts?.[projectId]?.[String(chapter.id)] || '').replace(/\r\n?/g, '\n').slice(0, 50_000),
    updatedAt: chapter.updatedAt || chapter.createdAt || '',
  }
}

function buildStoryFiles(db, project, chapter, instruction = '') {
  const cue = String(instruction || '')
  const chapterNumber = Number(chapter?.id)
  const chapterToken = Number.isFinite(chapterNumber) ? `第${String(chapterNumber).padStart(3, '0')}章` : ''
  const writingIntent = /续写|日更|继续写|接着写|正文|写第\s*[一二三四五六七八九十百千万两\d]+\s*章/.test(cue)
  const ideaRecords = (db.ideas || [])
    .filter((idea) => idea.userId === project.userId && idea.projectId === project.id && storyFilePath(idea))
  const chapterRecords = (db.chapters?.[project.id] || []).map((item) => ({
    id: `chapter:${item.id}`,
    title: item.title,
    body: db.drafts?.[project.id]?.[String(item.id)] || '',
    folder: '正文',
    label: '章节正文',
    tags: [`文件:${chapterStoryFilePath(item)}`],
    createdAt: item.createdAt,
    updatedAt: item.updatedAt,
    chapterId: item.id,
  }))
  const records = [...ideaRecords, ...chapterRecords]
    .map((idea) => {
      const path = storyFilePath(idea)
      let relevance = 0
      if (path.startsWith('正文/')) relevance += writingIntent ? 20 : 5
      if (String(idea.chapterId ?? '') === String(chapter?.id ?? '')) relevance += 30
      if (path === '大纲/大纲.md') relevance += 320
      if (path === '设定/题材定位.md') relevance += 270
      if (path === '设定/题材正文提示卡.md') relevance += 280
      if (writingIntent && path === '追踪/角色状态.md') relevance += 310
      if (writingIntent && path === '追踪/伏笔.md') relevance += 300
      if (writingIntent && path === '追踪/时间线.md') relevance += 290
      if (writingIntent && path === '追踪/上下文.md') relevance += 285
      if (/^大纲\/卷纲_/.test(path)) {
        relevance += 180
        const range = String(idea.body || '').match(/章节范围[：:]\s*第?\s*(\d+)\s*[-—~～至到]\s*第?\s*(\d+)\s*章/)
        if (chapterNumber && range && chapterNumber >= Number(range[1]) && chapterNumber <= Number(range[2])) relevance += 260
      }
      if (chapterToken && path.includes(`细纲_${chapterToken}`)) relevance += 500
      if (!writingIntent && /开书|大纲|卷纲|细纲|剧情/.test(cue) && path.startsWith('大纲/')) relevance += 100
      if (/设定|世界观|人物|角色|势力|关系/.test(cue) && path.startsWith('设定/')) relevance += 100
      if (/追踪|伏笔|时间线|状态/.test(cue) && path.startsWith('追踪/')) relevance += 100
      return { idea, path, relevance }
    })
    .sort((left, right) => right.relevance - left.relevance
      || String(right.idea.updatedAt || '').localeCompare(String(left.idea.updatedAt || '')))

  const inventory = records.slice(0, 80).map(({ idea, path }) => ({
    path,
    title: idea.title,
    category: idea.folder || idea.label || path.split('/')[0] || '资料',
    updatedAt: idea.updatedAt || idea.createdAt || '',
  }))
  const loaded = []
  let remaining = 48_000
  for (const { idea, path } of records) {
    if (loaded.length >= 10 || remaining <= 0) break
    if (path.startsWith('正文/') && String(idea.chapterId ?? '') !== String(chapter?.id ?? '')) continue
    const content = contextExcerpt(idea.body, Math.min(10_000, remaining))
    if (!content) continue
    loaded.push({
      path,
      title: idea.title,
      category: idea.folder || idea.label || path.split('/')[0] || '资料',
      content,
    })
    remaining -= content.length
  }
  return { inventory, loaded }
}

function draftMapFor(db, projectId) {
  const current = db.drafts[projectId]
  return current && typeof current === 'object' && !Array.isArray(current) ? current : {}
}

function chapterSummaryMap(memories) {
  const summaries = new Map()
  for (const memory of memories) {
    if (memory.type !== 'chapter_summary' || !memory.sourceChapterId || memory.status === 'archived') continue
    const key = String(memory.sourceChapterId)
    if (!summaries.has(key) || Number(memory.importance || 0) > Number(summaries.get(key).importance || 0)) {
      summaries.set(key, memory)
    }
  }
  return summaries
}

function summarizedChapter(chapter, drafts, summaries, maxLength = 900) {
  const summary = summaries.get(String(chapter.id))
  const fallback = [chapter.outline, contextExcerpt(drafts[String(chapter.id)], 500)].filter(Boolean).join('\n')
  return {
    id: chapter.id,
    title: chapter.title,
    summary: contextExcerpt(summary?.content || fallback, maxLength),
    summarySource: summary ? 'memory' : 'outline_fallback',
  }
}

function referenceError() {
  return Object.assign(new Error('引用内容不存在或不属于当前作品'), { status: 404 })
}

function referenceContent(db, project, userId, reference) {
  const type = String(reference?.type || '')
  const id = String(reference?.id || '')
  if (!type || !id) throw Object.assign(new Error('引用格式无效'), { status: 400 })
  if (type === 'project') {
    if (id !== String(project.id)) throw referenceError()
    return {
      name: `${project.title}.story.md`,
      kind: '作品设定',
      content: `# ${project.title}\n\n篇幅：${project.type || '未设置'}\n题材：${project.genre || '未设置'}\n流派：${project.style || '未设置'}\n创作基调：${project.tone || '未设置'}`,
    }
  }
  if (type === 'chapter') {
    const chapter = (db.chapters[project.id] || []).find((item) => String(item.id) === id)
    if (!chapter) throw referenceError()
    const content = draftMapFor(db, project.id)[String(chapter.id)] || ''
    return {
      name: `${String(chapter.id).padStart(2, '0')}-${chapter.title}.md`,
      kind: '章节正文',
      content: `# ${chapter.title}\n\n章节大纲：${chapter.outline || '未设置'}\n\n${content}`,
    }
  }
  if (type === 'idea') {
    const idea = (db.ideas || []).find((item) => String(item.id) === id && item.userId === userId && (!item.projectId || item.projectId === project.id))
    if (!idea) throw referenceError()
    return {
      name: idea.title,
      kind: idea.label || '灵感卡片',
      content: `# ${idea.title}\n\n${idea.body || ''}\n\n标签：${(idea.tags || []).join('、') || '无'}`,
    }
  }
  if (type === 'foreshadow') {
    const item = (db.foreshadows || []).find((value) => String(value.id) === id && value.userId === userId && value.projectId === project.id)
    if (!item) throw referenceError()
    return {
      name: item.title,
      kind: '伏笔',
      content: `# ${item.title}\n\n状态：${item.status || '未设置'}\n重要度：${item.importance || 3}\n\n${item.content || ''}`,
    }
  }
  if (type === 'memory') {
    const item = (db.storyMemories || []).find((value) => String(value.id) === id && value.userId === userId && value.projectId === project.id && value.status !== 'archived')
    if (!item) throw referenceError()
    return {
      name: item.title,
      kind: '作品记忆',
      content: `# ${item.title}\n\n类型：${item.type || '未设置'}\n重要度：${item.importance || 3}\n\n${item.content || ''}`,
    }
  }
  throw Object.assign(new Error(`不支持的引用类型：${type}`), { status: 400 })
}

export function resolveStoryAttachments(db, project, userId, attachments) {
  if (!Array.isArray(attachments)) return []
  return attachments.slice(0, 6).map((attachment) => {
    const reference = attachment?.reference && typeof attachment.reference === 'object'
      ? { type: String(attachment.reference.type || ''), id: String(attachment.reference.id || '') }
      : null
    const resolved = reference ? referenceContent(db, project, userId, reference) : null
    return {
      name: contextExcerpt(resolved?.name || attachment?.name, 240),
      kind: contextExcerpt(resolved?.kind || attachment?.kind || '外部文件', 80),
      content: contextExcerpt(resolved?.content || attachment?.content, 60_000),
      ...(reference ? { reference } : {}),
    }
  }).filter((item) => item.name && item.content)
}

export function buildWritingContext(db, project, chapter, instruction = '') {
  const chapters = db.chapters[project.id] || []
  const chapterIndex = chapters.findIndex((item) => String(item.id) === String(chapter.id))
  const drafts = draftMapFor(db, project.id)
  const previousChapters = chapters
    .slice(Math.max(0, chapterIndex - 6), chapterIndex)
    .map((item) => ({
      id: item.id,
      title: item.title,
      outline: contextExcerpt(item.outline, 900),
      ending: contextExcerpt(drafts[String(item.id)], 1200).slice(-1200),
    }))
  const storyFiles = buildStoryFiles(db, project, chapter, instruction)
  const materials = db.ideas
    .filter((idea) => idea.userId === project.userId
      && (!idea.projectId || idea.projectId === project.id)
      && !taggedStoryFilePath(idea))
    .sort((left, right) => Number(Boolean(right.pinned)) - Number(Boolean(left.pinned)) || String(right.updatedAt || '').localeCompare(String(left.updatedAt || '')))
    .slice(0, 20)
    .map((idea) => ({ label: idea.label, title: idea.title, body: contextExcerpt(idea.body, 500), tags: idea.tags || [] }))
  const unresolvedForeshadows = db.foreshadows
    .filter((item) => item.userId === project.userId && item.projectId === project.id && !['resolved', 'abandoned'].includes(item.status))
    .sort((left, right) => Number(right.importance || 0) - Number(left.importance || 0))
    .slice(0, 20)
    .map((item) => ({ title: item.title, content: contextExcerpt(item.content, 700), status: item.status, targetChapterId: item.targetChapterId || null }))
  const projectMemories = (db.storyMemories || [])
    .filter((item) => item.userId === project.userId && item.projectId === project.id && item.status !== 'archived')
  const summaries = chapterSummaryMap(projectMemories)
  const priorChapters = chapters.slice(0, Math.max(0, chapterIndex))
  const nearChapters = priorChapters.slice(-3).map((item) => ({
    id: item.id,
    title: item.title,
    outline: contextExcerpt(item.outline, 900),
    ending: contextExcerpt(drafts[String(item.id)], 1600).slice(-1600),
  }))
  const midChapters = priorChapters.slice(Math.max(0, priorChapters.length - 12), Math.max(0, priorChapters.length - 3))
    .map((item) => summarizedChapter(item, drafts, summaries, 900))
  const farSource = priorChapters.slice(0, Math.max(0, priorChapters.length - 12))
  const farChapters = farSource.slice(-40).map((item) => summarizedChapter(item, drafts, summaries, 500))
  const summaryStatus = {
    previousChapterCount: priorChapters.length,
    summarizedChapterCount: priorChapters.filter((item) => summaries.has(String(item.id))).length,
    missingChapterIds: priorChapters.filter((item) => !summaries.has(String(item.id))).map((item) => item.id),
  }
  summaryStatus.complete = summaryStatus.missingChapterIds.length === 0
  const storyMemory = projectMemories
    .sort((left, right) => (STORY_MEMORY_ORDER.get(left.type) ?? 99) - (STORY_MEMORY_ORDER.get(right.type) ?? 99)
      || Number(right.importance || 0) - Number(left.importance || 0)
      || String(right.updatedAt || '').localeCompare(String(left.updatedAt || '')))
    .slice(0, 60)
    .map((item) => ({
      id: item.id,
      type: item.type,
      title: item.title,
      content: contextExcerpt(item.content, 900),
      importance: item.importance || 3,
      characterName: item.characterName || '',
      sourceChapterId: item.sourceChapterId || null,
      tags: item.tags || [],
    }))
  return {
    version: 4,
    project: { id: project.id, title: project.title, type: project.type, genre: project.genre, style: project.style || '', premise: project.tone || '' },
    chapter: { id: chapter.id, title: chapter.title, outline: contextExcerpt(chapter.outline, 2400), state: chapter.state },
    storyFiles,
    previousChapters,
    layers: {
      near: { strategy: 'outline_and_ending', chapters: nearChapters },
      mid: { strategy: 'summary_with_outline_fallback', chapters: midChapters },
      far: { strategy: 'summary_catalog', chapters: farChapters, omittedChapterCount: Math.max(0, farSource.length - farChapters.length) },
    },
    summaryStatus,
    storyMemory,
    materials,
    unresolvedForeshadows,
    relationshipGraph: db.relationshipGraphs?.[project.id] || { nodes: [], edges: [] },
  }
}

export function enrichStoryAgentPayload(db, userId, payload, instruction = '') {
  const projectId = payload.project_id || payload.projectId
  const chapterId = payload.chapter_id || payload.chapterId
  if (!projectId) return payload
  const project = db.projects.find((item) => item.id === projectId && item.userId === userId)
  if (!project) throw Object.assign(new Error('作品不存在'), { status: 404 })
  const chapter = chapterId
    ? (db.chapters[project.id] || []).find((item) => String(item.id) === String(chapterId))
    : null
  if (chapterId && !chapter) throw Object.assign(new Error('章节不存在'), { status: 404 })
  const writingContext = chapter
    ? buildWritingContext(db, project, chapter, instruction)
    : {
      version: 2,
      project: { id: project.id, title: project.title, type: project.type, genre: project.genre, style: project.style || '', premise: project.tone || '' },
      storyFiles: buildStoryFiles(db, project, null, instruction),
      relationshipGraph: db.relationshipGraphs?.[project.id] || { nodes: [], edges: [] },
    }
  const attachedFiles = resolveStoryAttachments(db, project, userId, payload.attached_files)
  const requestedPolicy = payload.tool_policy && typeof payload.tool_policy === 'object' ? payload.tool_policy : {}
  const toolPolicy = {
    version: 1,
    readProjectContext: 'allow',
    externalSearch: requestedPolicy.externalSearch === 'allow' ? 'allow' : 'deny',
    mutateStoryData: requestedPolicy.mutateStoryData === 'allow' ? 'allow' : 'propose',
    deleteStoryData: 'deny',
    localShell: process.env.AUTH_MODE === 'local' ? 'allow' : 'deny',
  }
  return { ...payload, attached_files: attachedFiles, writing_context: writingContext, tool_policy: toolPolicy }
}

import crypto from 'node:crypto'
import { chapterStoryFilePath } from './writing-context.mjs'

function text(value, limit) {
  return String(value || '').replace(/\s+/g, ' ').trim().slice(0, limit)
}

function list(value, limit) {
  return Array.isArray(value) ? value.slice(0, limit) : []
}

function artifactDocument(item) {
  if (!item || typeof item !== 'object' || Array.isArray(item)) return null
  const rawPath = String(item.path || item.file || '').replaceAll('\\', '/').trim().slice(0, 240)
  if (rawPath.startsWith('/') || /^[A-Za-z]:\//.test(rawPath)) return null
  const parts = rawPath.split('/').filter(Boolean)
  if (!parts.length || parts.some((part) => part === '.' || part === '..' || part.includes('\0'))) return null
  const path = parts.join('/')
  const content = String(item.content || item.body || item.text || '').replace(/\r\n?/g, '\n').trim().slice(0, 50_000)
  const fallbackTitle = parts.at(-1).replace(/\.[^.]+$/, '')
  const title = text(item.title || fallbackTitle, 160)
  const category = text(item.category || parts[0] || '资料', 40)
  if (!path || !title || !content) return null
  return { path, title, category, content }
}

export function relationshipGraph(artifacts) {
  const raw = artifacts?.relationship_graph || artifacts?.relationships
    || ((artifacts?.nodes || artifacts?.edges) ? artifacts : null)
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null
  const nodes = Array.isArray(raw.nodes) ? raw.nodes
    .map((item) => item && typeof item === 'object' && !Array.isArray(item)
      ? {
        id: String(item.id || item.name || item.title || '').trim().slice(0, 120),
        name: String(item.name || item.title || item.id || '').trim().slice(0, 120),
        role: String(item.role || '').trim().slice(0, 80),
      }
      : null)
    .filter((item) => item && item.id && item.name)
    .slice(0, 120) : []
  const edges = Array.isArray(raw.edges) ? raw.edges
    .map((item) => item && typeof item === 'object' && !Array.isArray(item)
      ? {
        source: String(item.source || item.from || '').trim().slice(0, 120),
        target: String(item.target || item.to || '').trim().slice(0, 120),
        label: String(item.label || item.relationship || '').trim().slice(0, 120),
        kind: String(item.kind || item.type || '').trim().slice(0, 40),
      }
      : null)
    .filter((item) => item && item.source && item.target)
    .slice(0, 240) : []
  if (!nodes.length && !edges.length) return null
  return { nodes, edges }
}

function nextChapterId(chapters) {
  return chapters.reduce((maximum, chapter) => Math.max(maximum, Number(chapter.id) || 0), 0) + 1
}

function isBlankDefaultChapter(chapter, draft) {
  return !text(chapter?.outline, 1)
    && !text(draft, 1)
    && /^(?:第\s*[一二三四五六七八九十百千万两\d]+\s*章|未命名章节?)$/.test(text(chapter?.title, 100))
}

export function summarizeStoryArtifacts(artifacts) {
  if (!artifacts || typeof artifacts !== 'object' || Array.isArray(artifacts)) return null
  const projectUpdated = Boolean(artifacts.project && typeof artifacts.project === 'object'
    && ['genre', 'style', 'premise'].some((key) => text(artifacts.project[key], 1)))
  const characters = list(artifacts.characters, 24).filter((item) => item && typeof item === 'object' && text(item.name || item.title, 1) && text(item.description || item.body || item.summary, 1))
  const worldbuilding = list(artifacts.worldbuilding, 40).filter((item) => item && typeof item === 'object' && text(item.title || item.name, 1) && text(item.content || item.body || item.description, 1))
  const chapters = list(artifacts.chapters, 100).filter((item) => item && typeof item === 'object' && text(item.title || item.name, 1) && text(item.outline || item.content || item.summary, 1))
  const documents = list(artifacts.documents || artifacts.files, 80).map(artifactDocument).filter(Boolean)
  const graph = relationshipGraph(artifacts)
  const preview = {
    projectUpdated,
    characters: characters.length,
    worldbuilding: worldbuilding.length,
    chapters: chapters.length,
    documents: documents.length,
    targets: [
      ...(projectUpdated ? [{ kind: '作品', title: '基础设定' }] : []),
      ...characters.map((item) => ({ kind: '人物卡', title: text(item.name || item.title, 80) })),
      ...worldbuilding.map((item) => ({ kind: '世界观', title: text(item.title || item.name, 120) })),
      ...chapters.map((item) => ({ kind: '章节大纲', title: text(item.title || item.name, 100) })),
      ...documents.map((item) => ({ kind: item.category || '资料文件', title: item.title })),
      ...(graph ? [{ kind: '人物关系图', title: `${graph.nodes.length} 个角色 / ${graph.edges.length} 条关系` }] : []),
    ].slice(0, 24),
  }
  if (graph) preview.relationships = { nodes: graph.nodes.length, edges: graph.edges.length }
  const parts = [
    preview.projectUpdated ? '作品设定' : '',
    preview.characters ? `${preview.characters} 张人物卡` : '',
    preview.worldbuilding ? `${preview.worldbuilding} 条世界观` : '',
    preview.chapters ? `${preview.chapters} 章大纲` : '',
    preview.documents ? `${preview.documents} 份资料文件` : '',
    graph ? `人物关系图（${graph.nodes.length} 角色 / ${graph.edges.length} 关系）` : '',
  ].filter(Boolean)
  if (!parts.length) return null
  return { ...preview, summary: `准备写入${parts.join('、')}` }
}

function upsertIdea(db, {
  userId,
  projectId,
  label,
  title,
  body,
  folder,
  tags,
  color,
  sourcePath = '',
  timestamp,
}) {
  const normalizedTitle = title.toLocaleLowerCase('zh-CN')
  const pathTag = sourcePath ? `文件:${sourcePath}` : ''
  const existing = db.ideas.find((idea) => idea.userId === userId
    && idea.projectId === projectId
    && (pathTag
      ? (Array.isArray(idea.tags) && idea.tags.includes(pathTag))
        || (!(idea.tags || []).some((tag) => String(tag).startsWith('文件:'))
          && text(idea.title, 160).toLocaleLowerCase('zh-CN') === normalizedTitle
          && idea.folder === folder)
      : text(idea.title, 160).toLocaleLowerCase('zh-CN') === normalizedTitle && idea.folder === folder))
  if (existing) {
    existing.label = label
    existing.body = body
    existing.tags = tags
    existing.folder = folder
    existing.updatedAt = timestamp
    return { record: existing, created: false }
  }
  const record = {
    id: crypto.randomUUID(),
    userId,
    projectId,
    label,
    title,
    body,
    color,
    folder,
    tags,
    pinned: false,
    createdAt: timestamp,
    updatedAt: timestamp,
  }
  db.ideas.unshift(record)
  return { record, created: true }
}

export function applyStoryArtifacts(db, {
  userId,
  projectId,
  artifacts,
  timestamp = new Date().toISOString(),
} = {}) {
  const project = db?.projects?.find((item) => item.id === projectId && item.userId === userId)
  if (!project || !artifacts || typeof artifacts !== 'object' || Array.isArray(artifacts)) {
    return { applied: false, summary: '', characters: 0, worldbuilding: 0, chapters: 0, documents: 0, fileChanges: [], projectUpdated: false }
  }
  db.ideas ||= []
  db.chapters ||= {}
  db.drafts ||= {}
  db.editHistory ||= {}
  db.relationshipGraphs ||= {}
  const chapters = db.chapters[project.id] ||= []
  const drafts = db.drafts[project.id] ||= {}
  const history = db.editHistory[project.id] ||= {}
  let projectUpdated = false
  const projectArtifact = artifacts.project && typeof artifacts.project === 'object' ? artifacts.project : {}
  const projectUpdates = {
    genre: text(projectArtifact.genre, 30),
    style: text(projectArtifact.style, 80),
    tone: text(projectArtifact.premise, 2000),
  }
  for (const [key, value] of Object.entries(projectUpdates)) {
    if (value && project[key] !== value) {
      project[key] = value
      projectUpdated = true
    }
  }

  let characterCount = 0
  for (const item of list(artifacts.characters, 24)) {
    if (!item || typeof item !== 'object') continue
    const name = text(item.name || item.title, 80)
    const description = text(item.description || item.body || item.summary, 4000)
    const role = text(item.role, 80)
    if (!name || !description) continue
    upsertIdea(db, {
      userId,
      projectId,
      label: role || '人物',
      title: name,
      body: description,
      folder: '人物',
      tags: role ? [role] : [],
      color: 'coral',
      timestamp,
    })
    characterCount += 1
  }

  let worldbuildingCount = 0
  for (const item of list(artifacts.worldbuilding, 40)) {
    if (!item || typeof item !== 'object') continue
    const title = text(item.title || item.name, 160)
    const content = text(item.content || item.body || item.description, 4000)
    if (!title || !content) continue
    upsertIdea(db, {
      userId,
      projectId,
      label: '世界设定',
      title,
      body: content,
      folder: '世界观',
      tags: ['设定'],
      color: 'teal',
      timestamp,
    })
    worldbuildingCount += 1
  }

  let chapterCount = 0
  let blankChapter = chapters.find((chapter) => isBlankDefaultChapter(chapter, drafts[String(chapter.id)]))
  for (const item of list(artifacts.chapters, 100)) {
    if (!item || typeof item !== 'object') continue
    const title = text(item.title || item.name, 100)
    const outline = text(item.outline || item.content || item.summary, 5000)
    if (!title || !outline) continue
    let chapter = chapters.find((candidate) => text(candidate.title, 100) === title)
    if (!chapter && blankChapter) {
      chapter = blankChapter
      blankChapter = null
      chapter.title = title
    }
    if (!chapter) {
      chapter = {
        id: nextChapterId(chapters),
        title,
        outline: '',
        words: '0',
        state: 'draft',
        createdAt: timestamp,
        updatedAt: timestamp,
      }
      chapters.push(chapter)
      drafts[String(chapter.id)] = ''
      history[String(chapter.id)] = []
    }
    chapter.outline = outline
    chapter.updatedAt = timestamp
    upsertIdea(db, {
      userId,
      projectId,
      label: '章节大纲',
      title,
      body: outline,
      folder: '大纲',
      tags: ['Agent产物', '章节大纲'],
      color: 'yellow',
      timestamp,
    })
    chapterCount += 1
  }

  let documentCount = 0
  let relationshipCount = 0
  const fileChanges = []
  for (const item of list(artifacts.documents || artifacts.files, 80).map(artifactDocument).filter(Boolean)) {
    const folder = text(item.category || item.path.split('/')[0] || '资料', 40)
    const targetChapter = chapters.find((chapter) => chapterStoryFilePath(chapter) === item.path)
    if (targetChapter) {
      const key = String(targetChapter.id)
      const previous = typeof drafts[key] === 'string' ? drafts[key] : ''
      if (previous && previous !== item.content) {
        const snapshots = history[key] ||= []
        snapshots.push({
          id: crypto.randomUUID(),
          content: previous,
          words: previous.replace(/\s/g, '').length,
          createdAt: timestamp,
        })
        history[key] = snapshots.slice(-80)
      }
      drafts[key] = item.content
      targetChapter.words = item.content.replace(/\s/g, '').length.toLocaleString('en-US')
      targetChapter.updatedAt = timestamp
      fileChanges.push({
        id: `chapter:${targetChapter.id}`,
        path: item.path,
        title: targetChapter.title,
        category: '正文',
        action: 'updated',
      })
      documentCount += 1
      continue
    }
    const label = text(folder === '大纲' ? '大纲文档' : `${folder}文档`, 20)
    const change = upsertIdea(db, {
      userId,
      projectId,
      label,
      title: item.title,
      body: item.content,
      folder,
      tags: ['Skill产物', `文件:${item.path}`],
      color: folder === '大纲' ? 'yellow' : folder === '人物' ? 'coral' : 'teal',
      sourcePath: item.path,
      timestamp,
    })
    fileChanges.push({
      id: change.record.id,
      path: item.path,
      title: item.title,
      category: folder,
      action: change.created ? 'created' : 'updated',
    })
    documentCount += 1
  }

  const graph = relationshipGraph(artifacts)
  if (graph) {
    db.relationshipGraphs[projectId] = {
      nodes: graph.nodes,
      edges: graph.edges,
      updatedAt: timestamp,
    }
    relationshipCount = 1
  }

  const applied = projectUpdated || characterCount > 0 || worldbuildingCount > 0 || chapterCount > 0 || documentCount > 0 || relationshipCount > 0
  if (applied) {
    project.chapters = chapters.length
    project.words = chapters.reduce((total, chapter) => {
      return total + String(drafts[String(chapter.id)] || '').replace(/\s/g, '').length
    }, 0).toLocaleString('en-US')
    project.updated = '刚刚'
    project.updatedAt = timestamp
  }
  const parts = [
    projectUpdated ? '作品设定' : '',
    characterCount ? `${characterCount} 张人物卡` : '',
    worldbuildingCount ? `${worldbuildingCount} 条世界观` : '',
    chapterCount ? `${chapterCount} 章大纲` : '',
    documentCount ? `${documentCount} 份资料文件` : '',
    graph ? `人物关系图（${graph.nodes.length} 角色 / ${graph.edges.length} 关系）` : '',
  ].filter(Boolean)
  return {
    applied,
    summary: parts.length ? `已写入${parts.join('、')}` : '',
    characters: characterCount,
    worldbuilding: worldbuildingCount,
    chapters: chapterCount,
    documents: documentCount,
    relationships: relationshipCount ? { nodes: graph.nodes.length, edges: graph.edges.length } : null,
    fileChanges,
    projectUpdated,
  }
}

import crypto from 'node:crypto'
import {
  STORY_AGENT_RUNTIME_INFO,
  listStorySkills,
  runContextCompaction,
  runStoryAgent,
  runStoryDelegate,
  storyAgentModelCapabilities as resolveStoryAgentModelCapabilities,
} from '../src/agent-runtime.ts'
import { decryptSecret } from './auth.mjs'
import { loadDb, updateDb } from './store.mjs'
import { importWorkspaceChanges, materializeProjectWorkspace, projectWorkspaceDir, writeWorkspaceFile } from './local-workspace.mjs'
import { activeModelSettings } from './model-settings.mjs'
import { enrichStoryAgentPayload } from './writing-context.mjs'
import { decorateInstalledMarketSkill } from './market-skill-runtime.mjs'
import { readStoryDocument, writeStoryDocument } from './story-document-store.mjs'

const sharedModelAccessAllowed = process.env.ALLOW_SHARED_MODEL_KEY === 'true'

function isNetworkError(error) {
  return error?.name === 'TimeoutError'
    || error?.name === 'TypeError'
    || ['ECONNREFUSED', 'ENOTFOUND', 'EAI_AGAIN', 'ECONNRESET'].includes(error?.cause?.code)
}

export function storyAgentModelConfig(user) {
  if (!user?.settings) return sharedModelAccessAllowed ? null : { provider: 'openai', allow_server_fallback: false }
  const settings = activeModelSettings(user.settings)
  return {
    provider: settings.provider === 'anthropic' ? 'anthropic' : 'openai',
    api_base_url: settings.apiBaseUrl || undefined,
    api_key: decryptSecret(settings.apiKeyEnc) || undefined,
    model: settings.model || undefined,
    reasoning_effort: settings.reasoningEffort || undefined,
    thinking_budgets: settings.thinkingBudgets || undefined,
    temperature: settings.temperature ?? undefined,
    context_window: settings.contextWindow ?? undefined,
    allow_server_fallback: sharedModelAccessAllowed,
  }
}

export function storyAgentModelCapabilities(settings = {}) {
  const resolved = Array.isArray(settings?.modelProfiles) ? activeModelSettings(settings) : settings
  return resolveStoryAgentModelCapabilities({
    provider: resolved.provider === 'anthropic' ? 'anthropic' : 'openai',
    api_base_url: resolved.apiBaseUrl || undefined,
    model: resolved.model || undefined,
    reasoning_effort: resolved.reasoningEffort || undefined,
    context_window: resolved.contextWindow ?? undefined,
  })
}

async function preparedStoryAgentBody(user, input) {
  const db = await loadDb()
  const payload = enrichStoryAgentPayload(db, user.id, input.payload || {}, input.message)
  const prepared = await decorateInstalledMarketSkill(user.id, { ...input, payload })
  return {
    message: prepared.message,
    skill: prepared.skill || null,
    payload: prepared.payload,
    model_config: storyAgentModelConfig(user),
  }
}

export async function invokeStoryAgent(
  user,
  input,
  signal = undefined,
  onDelta = null,
  onReasoningDelta = null,
  onToolEvent = null,
  onAssistantMessageEvent = null,
) {
  const body = await preparedStoryAgentBody(user, input)
  const projectId = body.payload?.project_id || body.payload?.projectId || null
  const canPersistStoryFiles = body.payload?.tool_policy?.mutateStoryData === 'allow'
  const localShellWorkspace = projectId && process.env.AUTH_MODE === 'local'
    ? projectWorkspaceDir(projectId)
    : null
  if (localShellWorkspace) {
    const db = await loadDb()
    await materializeProjectWorkspace(db, user.id, projectId, localShellWorkspace)
  }
  try {
    return await runStoryAgent(body, {
      signal,
      onDelta: onDelta || undefined,
      onReasoningDelta: onReasoningDelta || undefined,
      onToolEvent: onToolEvent || undefined,
      onAssistantMessageEvent: onAssistantMessageEvent || undefined,
      localShellWorkspace: localShellWorkspace || undefined,
      readStoryFile: projectId
        ? async (path) => readStoryDocument(user.id, projectId, path)
        : undefined,
      writeStoryFile: projectId && canPersistStoryFiles
        ? async (file) => {
            const result = await writeStoryDocument(user.id, projectId, file)
            if (localShellWorkspace) {
              await writeWorkspaceFile(localShellWorkspace, file.path, file.content).catch(() => false)
            }
            return result
          }
        : undefined,
    })
  } finally {
    if (localShellWorkspace) {
      await updateDb((db) => importWorkspaceChanges(db, user.id, projectId, localShellWorkspace)).catch(() => {})
    }
  }
}

function delegateRoles(input) {
  const skill = String(input?.skill || '')
  if (input?.payload?.multi_agent !== true) return []
  if (/(?:review|analyze|scan|deslop)/.test(skill)) return ['continuity_guard', 'prose_critic']
  return ['continuity_guard', 'scene_planner']
}

export async function invokeStoryAgentDelegates(user, input, signal = undefined, onEvent = null) {
  const roles = delegateRoles(input)
  if (!roles.length) return []
  const body = await preparedStoryAgentBody(user, input)
  const projectId = body.payload?.project_id || body.payload?.projectId || null
  const runs = roles.map(async (role, ordinal) => {
    const id = `${role}:${ordinal + 1}`
    const runId = crypto.randomUUID()
    await onEvent?.({
      id,
      runId,
      path: `/root/${role}`,
      role,
      ordinal,
      status: 'running',
      startedAt: new Date().toISOString(),
    })
    try {
      const result = await runStoryDelegate({ ...body, role }, {
        signal,
        readStoryFile: projectId
          ? async (path) => readStoryDocument(user.id, projectId, path)
          : undefined,
      })
      const completed = {
        id,
        runId,
        path: `/root/${role}`,
        role,
        ordinal,
        status: result.status,
        summary: typeof result.summary === 'string' ? result.summary.slice(0, 6_000) : '',
        usage: result.usage,
        error: result.error || null,
        completedAt: new Date().toISOString(),
      }
      await onEvent?.(completed)
      return completed
    } catch (error) {
      if (signal?.aborted) throw error
      const failed = {
        id,
        runId,
        path: `/root/${role}`,
        role,
        ordinal,
        status: 'failed',
        summary: '',
        usage: null,
        error: '子代理审阅失败，主代理已降级继续',
        completedAt: new Date().toISOString(),
      }
      await onEvent?.(failed)
      return failed
    }
  })
  return Promise.all(runs)
}

export async function invokeContextCompaction(user, input, signal = AbortSignal.timeout(300_000)) {
  return await runContextCompaction(storyAgentModelConfig(user), {
    existingSummary: typeof input?.existingSummary === 'string' ? input.existingSummary : '',
    messages: Array.isArray(input?.messages) ? input.messages : [],
    instructions: typeof input?.instructions === 'string' ? input.instructions : '',
  }, { signal })
}

export async function listStoryAgentSkills() {
  return await listStorySkills()
}

export function storyAgentRuntimeInfo() {
  return STORY_AGENT_RUNTIME_INFO
}

export function classifyTaskError(error, cancelled = false) {
  if (cancelled) return { errorCode: 'cancelled', retryable: true, message: '任务已取消，可重新提交' }
  if (error?.name === 'TimeoutError' || error?.name === 'AbortError') return { errorCode: 'timeout', retryable: true, message: '模型响应超时，可重试此任务' }
  if (isNetworkError(error) || error?.status === 502 || error?.status === 503) return { errorCode: 'service_unavailable', retryable: true, message: 'AI 服务暂不可用，可稍后重试' }
  if (error?.status === 400 && /模型|API Key|密钥|model/i.test(error?.message || '')) return { errorCode: 'model_config', retryable: false, message: '模型配置无效，请在设置中检查地址、密钥和模型名' }
  if (/上下文|字符|token|length/i.test(error?.message || '')) return { errorCode: 'context_too_large', retryable: false, message: '输入上下文过长，请缩短正文或素材后重试' }
  return { errorCode: 'unknown', retryable: true, message: error?.message || 'AI Skill 执行失败' }
}

import { mkdir, readdir, readFile, rm, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { applyStoryArtifacts } from './story-artifacts.mjs'
import { storeInfo } from './store.mjs'
import { chapterStoryFilePath, readStoryFileForAgent, storyFilePath } from './writing-context.mjs'

// 桌面端/本地模式专属：把作品的虚拟「作品文件」物化为真实目录，供本地命令/Skill 脚本操作；
// 任务结束后再把磁盘改动回收进数据库（applyStoryArtifacts 负责章节正文与资料的归位）。
const TEXT_EXTENSIONS = new Set(['.md', '.markdown', '.txt', '.json', '.yaml', '.yml', '.toml'])
const MAX_IMPORT_FILES = 400
const MAX_IMPORT_CHARS = 50_000

export function projectWorkspaceDir(projectId) {
  const dataFile = storeInfo().dataFile
  if (!dataFile) return null
  const safeId = String(projectId || '').replace(/[^\w-]/g, '_')
  if (!safeId) return null
  return path.join(path.dirname(dataFile), 'workspace', `project-${safeId}`)
}

function resolveInside(rootDir, relativePath) {
  const normalized = String(relativePath || '').replaceAll('\\', '/').trim()
  if (!normalized || normalized.startsWith('/') || /^[A-Za-z]:\//.test(normalized)) return null
  const parts = normalized.split('/').filter(Boolean)
  if (!parts.length || parts.some((part) => part === '.' || part === '..' || part.includes('\0'))) return null
  const resolved = path.resolve(rootDir, ...parts)
  const relative = path.relative(rootDir, resolved)
  if (relative.startsWith('..') || path.isAbsolute(relative)) return null
  return resolved
}

async function listWorkspaceFiles(rootDir) {
  const files = []
  const walk = async (dir) => {
    if (files.length >= MAX_IMPORT_FILES) return
    const entries = await readdir(dir, { withFileTypes: true }).catch(() => [])
    for (const entry of entries) {
      if (files.length >= MAX_IMPORT_FILES) return
      const full = path.join(dir, entry.name)
      if (entry.isDirectory()) await walk(full)
      else if (entry.isFile() && TEXT_EXTENSIONS.has(path.extname(entry.name).toLowerCase())) files.push(full)
    }
  }
  await walk(rootDir)
  return files
}

export function collectProjectFiles(db, userId, projectId) {
  const files = new Map()
  const project = db.projects?.find((item) => item.id === projectId && item.userId === userId)
  if (!project) return files
  const chapters = db.chapters?.[projectId] || []
  for (const chapter of chapters) {
    const relPath = chapterStoryFilePath(chapter)
    if (!relPath) continue
    files.set(relPath, String(db.drafts?.[projectId]?.[String(chapter.id)] || '').replace(/\r\n?/g, '\n'))
  }
  for (const idea of db.ideas || []) {
    if (idea.userId !== userId || idea.projectId !== projectId) continue
    const relPath = storyFilePath(idea)
    if (!relPath || files.has(relPath)) continue
    files.set(relPath, String(idea.body || '').replace(/\r\n?/g, '\n'))
  }
  return files
}

export async function materializeProjectWorkspace(db, userId, projectId, workspaceDir) {
  await rm(workspaceDir, { recursive: true, force: true })
  await mkdir(workspaceDir, { recursive: true })
  let written = 0
  for (const [relPath, content] of collectProjectFiles(db, userId, projectId)) {
    const target = resolveInside(workspaceDir, relPath)
    if (!target) continue
    await mkdir(path.dirname(target), { recursive: true })
    await writeFile(target, content, 'utf8')
    written += 1
  }
  return written
}

export async function writeWorkspaceFile(workspaceDir, relPath, content) {
  const target = resolveInside(workspaceDir, relPath)
  if (!target) return false
  await mkdir(path.dirname(target), { recursive: true })
  await writeFile(target, String(content ?? '').replace(/\r\n?/g, '\n'), 'utf8')
  return true
}

export function importWorkspaceChangesToState(db, userId, projectId, workspaceDir, diskFiles) {
  const documents = []
  for (const [absolutePath, content] of diskFiles) {
    if (!content.trim() || content.length > MAX_IMPORT_CHARS) continue
    const relPath = path.relative(workspaceDir, absolutePath).split(path.sep).join('/')
    const existing = readStoryFileForAgent(db, userId, projectId, relPath)
    if (existing && existing.content === content.trim()) continue
    documents.push({ path: relPath, content })
  }
  if (!documents.length) return { applied: false, imported: 0 }
  const application = applyStoryArtifacts(db, { userId, projectId, artifacts: { documents } })
  return { applied: application.applied, imported: application.documents || documents.length }
}

export async function importWorkspaceChanges(db, userId, projectId, workspaceDir) {
  const files = await listWorkspaceFiles(workspaceDir)
  const diskFiles = new Map()
  for (const absolutePath of files) {
    const content = await readFile(absolutePath, 'utf8').catch(() => null)
    if (typeof content === 'string') diskFiles.set(absolutePath, content.replace(/\r\n?/g, '\n'))
  }
  return importWorkspaceChangesToState(db, userId, projectId, workspaceDir, diskFiles)
}

