1	const TERMINAL_TASK_STATUSES = new Set(['completed', 'failed', 'cancelled'])
2	
3	function text(value) {
4	  return typeof value === 'string' ? value.trim() : ''
5	}
6	
7	function answerValues(value) {
8	  const raw = value && typeof value === 'object' && !Array.isArray(value) ? value.answers : value
9	  const values = Array.isArray(raw) ? raw : [raw]
10	  return [...new Set(values.map((item) => text(String(item ?? '')).slice(0, 1000)).filter(Boolean))].slice(0, 6)
11	}
12	
13	function positiveInteger(value) {
14	  const number = Number(value)
15	  return Number.isFinite(number) && number >= 0 ? Math.floor(number) : 0
16	}
17	
18	function normalizedUsage(value) {
19	  if (!value || typeof value !== 'object' || Array.isArray(value)) return null
20	  const usage = {
21	    input_tokens: positiveInteger(value.input_tokens),
22	    cached_input_tokens: positiveInteger(value.cached_input_tokens),
23	    output_tokens: positiveInteger(value.output_tokens),
24	    reasoning_output_tokens: positiveInteger(value.reasoning_output_tokens),
25	    total_tokens: positiveInteger(value.total_tokens),
26	    estimated: value.estimated === true,
27	  }
28	  if (!usage.total_tokens) usage.total_tokens = usage.input_tokens + usage.output_tokens
29	  return usage
30	}
31	
32	export function accumulateTaskUsage(task, response, timestamp = new Date().toISOString()) {
33	  if (!task || !response || typeof response !== 'object') return task?.usage || null
34	  const attemptUsage = normalizedUsage(response?.result?.usage || response?.usage)
35	  if (!attemptUsage) return task.usage || null
36	  const interactionAttempt = Math.max(1, positiveInteger(task.interactionAttempt) || 1)
37	  const history = Array.isArray(task.usageHistory) ? task.usageHistory : []
38	  const runId = text(response.run_id)
39	  if (runId && history.some((item) => item?.runId === runId)) {
40	    if (response.result && typeof response.result === 'object' && !Array.isArray(response.result) && task.usage) {
41	      response.result.usage = { ...task.usage }
42	    }
43	    return task.usage || null
44	  }
45	  const previous = normalizedUsage(task.usage) || normalizedUsage({})
46	  const usage = {
47	    input_tokens: previous.input_tokens + attemptUsage.input_tokens,
48	    cached_input_tokens: previous.cached_input_tokens + attemptUsage.cached_input_tokens,
49	    output_tokens: previous.output_tokens + attemptUsage.output_tokens,
50	    reasoning_output_tokens: previous.reasoning_output_tokens + attemptUsage.reasoning_output_tokens,
51	    total_tokens: previous.total_tokens + attemptUsage.total_tokens,
52	    estimated: previous.estimated || attemptUsage.estimated,
53	  }
54	  task.usage = usage
55	  task.usageHistory = [...history, {
56	    runId: runId || null,
57	    interactionAttempt,
58	    status: text(response.status) || 'completed',
59	    usage: attemptUsage,
60	    createdAt: timestamp,
61	  }].slice(-20)
62	  if (response.result && typeof response.result === 'object' && !Array.isArray(response.result)) {
63	    response.result.usage = { ...usage }
64	  }
65	  return usage
66	}
67	
68	function publicQuestion(question, index) {
69	  const options = Array.isArray(question?.options)
70	    ? question.options.slice(0, 6).map((option) => ({
71	      label: text(option?.label || option?.value).slice(0, 100),
72	      value: text(option?.value || option?.label).slice(0, 200),
73	      description: text(option?.description).slice(0, 300),
74	    })).filter((option) => option.label)
75	    : []
76	  return {
77	    id: text(question?.id) || `question_${index + 1}`,
78	    header: text(question?.header).slice(0, 80),
79	    question: text(question?.question).slice(0, 1000),
80	    options,
81	    isOther: question?.isOther !== false,
82	  }
83	}
84	
85	export function taskInputHistory(task) {
86	  const history = task?.input?.payload?.request_user_input_history
87	  if (!Array.isArray(history)) return []
88	  return history.slice(-6).map((entry, historyIndex) => {
89	    const rawQuestions = Array.isArray(entry?.questions) ? entry.questions : []
90	    const questions = rawQuestions.slice(0, 3).map(publicQuestion).filter((item) => item.question)
91	    const rawAnswers = entry?.response?.answers
92	    const answers = {}
93	    if (rawAnswers && typeof rawAnswers === 'object' && !Array.isArray(rawAnswers)) {
94	      for (const question of questions) {
95	        const values = answerValues(rawAnswers[question.id])
96	        if (values.length) answers[question.id] = { answers: values }
97	      }
98	    }
99	    const fallbackQuestionText = questions.map((item, index) => `${item.header || `问题 ${index + 1}`}：${item.question}`).join('\n')
100	    const fallbackAnswerText = questions.flatMap((item) => {
101	      const values = answerValues(answers[item.id])
102	      return values.length ? [`${item.header || item.question}：${values.join('、')}`] : []
103	    }).join('\n')
104	    return {
105	      requestId: text(entry?.requestId) || `${task?.id || 'task'}:request-user-input:${historyIndex + 1}`,
106	      interactionAttempt: Math.max(1, positiveInteger(entry?.interactionAttempt) || historyIndex + 1),
107	      questions,
108	      response: {
109	        answers,
110	        questionText: text(entry?.response?.questionText).slice(0, 4000) || fallbackQuestionText,
111	        answerText: text(entry?.response?.answerText).slice(0, 6000) || fallbackAnswerText,
112	      },
113	      requestedAt: entry?.requestedAt || null,
114	      resolvedAt: entry?.resolvedAt || null,
115	    }
116	  })
117	}
118	
119	export function reasoningItemId(task, turnId = null, interactionAttempt = null) {
120	  const attempt = Math.max(1, positiveInteger(interactionAttempt ?? task?.interactionAttempt) || 1)
121	  return `${turnId || task?.turnId || task?.id || 'task'}:reasoning:${attempt}`
