323	export function threadConversation(thread, tasks) {
324	  const taskMap = new Map((tasks || []).map((task) => [task.id, task]))
325	  const compactedTurnIds = new Set(thread?.compactedTurnIds || [])
326	  const completedTurns = (thread?.turns || [])
327	    .filter((turn) => taskMap.get(turn.taskId)?.status === 'completed' && !compactedTurnIds.has(turn.id))
