346	export const DEFAULT_THREAD_COMPACTION_SETTINGS = Object.freeze({
347	  enabled: true,
348	  strategy: 'context-full',
349	  thresholdPercent: -1,
350	  thresholdTokens: -1,
351	  reserveTokens: null,
352	  keepRecentTokens: 20000,
