360	export function normalizeThreadCompactionSettings(value) {
361	  const input = value && typeof value === 'object' && !Array.isArray(value) ? value : {}
362	  return {
363	    enabled: input.enabled !== false,
364	    strategy: input.strategy === 'off' ? 'off' : 'context-full',
365	    thresholdPercent: finiteNumber(input.thresholdPercent, -1),
366	    thresholdTokens: finiteNumber(input.thresholdTokens, -1),
367	    reserveTokens: input.reserveTokens == null ? null : Math.max(0, finiteNumber(input.reserveTokens, 0)),
368	    keepRecentTokens: Math.max(1, finiteNumber(input.keepRecentTokens, DEFAULT_THREAD_COMPACTION_SETTINGS.keepRecentTokens)),
369	  }
370	}
