372	export function resolveThreadCompactionThreshold(contextWindow, value) {
373	  const settings = normalizeThreadCompactionSettings(value)
374	  const safeWindow = Math.max(2, finiteNumber(contextWindow, 100000))
375	  if (settings.thresholdTokens > 0) {
376	    return Math.min(safeWindow - 1, Math.max(1, Math.floor(settings.thresholdTokens)))
377	  }
378	  if (settings.thresholdPercent > 0) {
379	    const percent = Math.min(99, Math.max(1, settings.thresholdPercent))
380	    return Math.floor(safeWindow * (percent / 100))
381	  }
382	  const proportionalReserve = Math.max(1, Math.floor(safeWindow * 0.15))
383	  const configuredReserve = settings.reserveTokens == null
384	    ? Math.max(proportionalReserve, DEFAULT_COMPACTION_RESERVE_TOKENS)
385	    : Math.max(proportionalReserve, settings.reserveTokens)
386	  const defaultReserveIsImpossible = settings.reserveTokens == null
387	    && configuredReserve >= safeWindow - proportionalReserve
388	  const reserve = defaultReserveIsImpossible || configuredReserve >= safeWindow
389	    ? proportionalReserve
390	    : configuredReserve
391	  return Math.max(0, Math.min(safeWindow - 1, safeWindow - reserve))
392	}
