398	export function threadCompactionPlan(thread, tasks, {
399	  contextWindow = 100000,
400	  compaction = DEFAULT_THREAD_COMPACTION_SETTINGS,
401	  force = false,
402	} = {}) {
403	  const settings = normalizeThreadCompactionSettings(compaction)
404	  if (!force && (!settings.enabled || settings.strategy === 'off')) return null
405	  const taskMap = new Map((tasks || []).map((task) => [task.id, task]))
406	  const compactedTurnIds = new Set(thread?.compactedTurnIds || [])
407	  const completedTurns = (thread?.turns || [])
408	    .filter((turn) => taskMap.get(turn.taskId)?.status === 'completed' && !compactedTurnIds.has(turn.id))
409	  if (completedTurns.length < 2) return null
410	
411	  const turnBatches = completedTurns.map((turn) => {
412	    const task = taskMap.get(turn.taskId)
413	    const messages = turnConversationMessages(turn, task)
414	    return { turn, messages, tokens: estimateConversationTokens(messages) }
415	  })
416	  const messages = turnBatches.flatMap((batch) => batch.messages)
417	  const safeWindow = Math.max(2, finiteNumber(contextWindow, 100000))
418	  const thresholdTokens = resolveThreadCompactionThreshold(safeWindow, settings)
419	  const summaryTokens = text(thread?.contextSummary) ? Math.ceil(text(thread.contextSummary).length / 2.2) : 0
420	  const estimatedTokens = summaryTokens + estimateConversationTokens(messages)
421	  if (!force && estimatedTokens <= thresholdTokens) return null
422	
423	  let keepStart = turnBatches.length
424	  let keptTokens = 0
425	  while (keepStart > 0 && (keptTokens < settings.keepRecentTokens || keepStart === turnBatches.length)) {
426	    keepStart -= 1
427	    keptTokens += turnBatches[keepStart].tokens
428	  }
429	  if (keepStart === 0 && turnBatches.length > 1 && (force || estimatedTokens > thresholdTokens)) keepStart = 1
430	  const batchesToCompact = turnBatches.slice(0, keepStart)
431	  if (!batchesToCompact.length) return null
432	  const turnsToCompact = batchesToCompact.map((batch) => batch.turn)
433	  const turnIds = turnsToCompact.map((turn) => turn.id)
434	  const messagesToCompact = batchesToCompact.flatMap((batch) => batch.messages)
435	  return {
436	    turnIds,
437	    messages: messagesToCompact,
438	    estimatedTokens,
439	    thresholdTokens,
440	    keepRecentTokens: settings.keepRecentTokens,
441	    keptTurnCount: completedTurns.length - turnsToCompact.length,
442	    forced: force,
443	  }
444	}
