630	      createdAt: task?.reasoningStartedAt || task?.updatedAt || task?.createdAt || null,
631	      completedAt: ['queued', 'running'].includes(task?.status) ? null : task?.reasoningCompletedAt || task?.updatedAt || null,
632	    })
633	  }
634	  const pendingInputRequest = task?.pendingInputRequest && typeof task.pendingInputRequest === 'object'
635	    ? task.pendingInputRequest
636	    : null
637	  const inputRequest = task?.result?.status === 'needs_input'
638	    ? task.result?.result?.question
639	    : pendingInputRequest
640	  if (inputRequest && typeof inputRequest === 'object') {
641	    const requestId = text(inputRequest.requestId) || `${turn.id}:request-user-input`
642	    items.push({
643	      id: requestId,
644	      type: 'requestUserInput',
645	      status: 'inProgress',
646	      requestId,
647	      questions: Array.isArray(inputRequest.questions) ? inputRequest.questions : [inputRequest],
648	      meta: { interactionAttempt: Math.max(1, positiveInteger(task?.interactionAttempt) || 1) },
649	      createdAt: task?.inputRequestStartedAt || pendingInputRequest?.requestedAt || task?.updatedAt || null,
650	    })
651	  }
652	  if (TERMINAL_TASK_STATUSES.has(task?.status)) {
653	    const planMode = task?.input?.payload?.collaboration_mode === 'plan'
