1	export interface StoryFileRecord {
2		path: string;
3		title: string;
4		category: string;
5		content?: string;
6		updatedAt?: string;
7	}
8	
9	interface StoryFileContext {
10		inventory?: unknown;
11		loaded?: unknown;
12	}
13	
14	export interface StoryFileWorkspace {
15		list(prefix?: string): StoryFileRecord[];
16		read(path: string): Promise<StoryFileRecord>;
17		write(file: StoryFileRecord): StoryFileRecord;
18		edit(path: string, oldText: string, newText: string, replaceAll?: boolean): Promise<StoryFileRecord>;
19		written(): StoryFileRecord[];
20	}
21	
22	const MAX_STORY_FILES = 80;
23	const MAX_STORY_FILE_CHARS = 50_000;
24	
25	function cleanText(value: unknown, limit: number): string {
26		return String(value ?? "").trim().slice(0, limit);
27	}
28	
29	export function normalizeStoryFilePath(value: unknown): string {
30		const raw = String(value ?? "").replaceAll("\\", "/").trim().slice(0, 240);
31		if (!raw || raw.startsWith("/") || /^[A-Za-z]:\//.test(raw)) throw new Error("作品文件路径必须是相对路径");
32		const parts = raw.split("/").filter(Boolean);
33		if (!parts.length || parts.some(part => part === "." || part === ".." || part.includes("\0"))) {
34			throw new Error("作品文件路径无效");
35		}
36		return parts.join("/");
37	}
38	
39	function fileRecord(value: unknown, requireContent = false): StoryFileRecord | null {
40		if (!value || typeof value !== "object" || Array.isArray(value)) return null;
41		const item = value as Record<string, unknown>;
42		let path: string;
43		try {
44			path = normalizeStoryFilePath(item.path ?? item.file);
45		} catch {
46			return null;
47		}
48		const fallbackTitle = path.split("/").at(-1)?.replace(/\.[^.]+$/, "") ?? "作品文件";
49		const title = cleanText(item.title || fallbackTitle, 160);
50		const category = cleanText(item.category || path.split("/")[0] || "资料", 40);
51		const contentValue = item.content ?? item.body ?? item.text;
52		const content = typeof contentValue === "string"
53			? contentValue.replace(/\r\n?/g, "\n").trim().slice(0, MAX_STORY_FILE_CHARS)
54			: undefined;
55		if (!title || !category || (requireContent && !content)) return null;
56		return {
57			path,
58			title,
59			category,
60			...(content !== undefined ? { content } : {}),
61			...(typeof item.updatedAt === "string" ? { updatedAt: item.updatedAt } : {}),
62		};
63	}
64	
65	function contextFiles(payload: Record<string, unknown>): StoryFileContext {
66		const writingContext = payload.writing_context;
67		if (!writingContext || typeof writingContext !== "object" || Array.isArray(writingContext)) return {};
68		const storyFiles = (writingContext as Record<string, unknown>).storyFiles;
69		return storyFiles && typeof storyFiles === "object" && !Array.isArray(storyFiles)
70			? (storyFiles as StoryFileContext)
71			: {};
72	}
73	
74	export function createStoryFileWorkspace(
75		payload: Record<string, unknown>,
76		readThrough?: (path: string) => Promise<StoryFileRecord | null>,
77	): StoryFileWorkspace {
78		const files = new Map<string, StoryFileRecord>();
79		const changes = new Map<string, StoryFileRecord>();
80		const context = contextFiles(payload);
81		for (const value of Array.isArray(context.inventory) ? context.inventory.slice(0, MAX_STORY_FILES) : []) {
82			const record = fileRecord(value);
83			if (record) files.set(record.path, record);
84		}
85		for (const value of Array.isArray(context.loaded) ? context.loaded.slice(0, MAX_STORY_FILES) : []) {
86			const record = fileRecord(value, true);
87			if (record) files.set(record.path, { ...files.get(record.path), ...record });
88		}
89	
90		async function read(pathValue: string): Promise<StoryFileRecord> {
91			const path = normalizeStoryFilePath(pathValue);
92			const current = files.get(path);
93			if (current?.content !== undefined) return { ...current };
94			const loaded = readThrough ? fileRecord(await readThrough(path), true) : null;
95			if (!loaded || loaded.path !== path) throw new Error(`作品文件不存在：${path}`);
96			const merged = { ...current, ...loaded };
97			files.set(path, merged);
98			return { ...merged };
99		}
100	
101		function write(value: StoryFileRecord): StoryFileRecord {
102			const record = fileRecord(value, true);
103			if (!record) throw new Error("作品文件必须包含有效的相对路径、标题和内容");
104			if (!files.has(record.path) && files.size >= MAX_STORY_FILES) throw new Error(`一次最多暂存 ${MAX_STORY_FILES} 个作品文件`);
105			const next = { ...files.get(record.path), ...record };
106			files.set(record.path, next);
107			changes.set(record.path, next);
108			return { ...next };
109		}
110	
111		return {
112			list(prefixValue = "") {
113				const prefix = String(prefixValue || "").replaceAll("\\", "/").replace(/^\/+/, "").trim();
114				return [...files.values()]
115					.filter(item => !prefix || item.path.startsWith(prefix))
116					.map(({ content: _content, ...item }) => ({ ...item }))
117					.sort((left, right) => left.path.localeCompare(right.path, "zh-CN"));
118			},
119			read,
120			write,
